78	/** Freeze only newly owned data; callers must never pass original input objects. */
79	export function freezeOwned<T>(value: T): T {
80	  if (value && typeof value === 'object') {
81	    for (const child of Object.values(value)) freezeOwned(child)
82	    Object.freeze(value)
83	  }
84	  return value
85	}

